trazabilidad_archivos.codigo_final:
:root {
  /* Paleta Cyberpunk */
  --color-bg-primary: #0a0a0f;
  --color-bg-secondary: #0f0f1a;
  --color-bg-panel: #12121f;
  --color-accent-cyan: #00f5ff;
  --color-accent-magenta: #ff00ff;
  --color-accent-yellow: #ffd700;
  --color-text-primary: #e0e0ff;
  --color-text-secondary: #8888aa;
  --color-text-muted: #444466;
  --color-border-subtle: #1e1e3a;
  --color-danger: #ff3366;
  --color-success: #00ff88;

  /* Tipografía */
  --font-display: 'Orbitron', monospace;
  --font-body: 'Share Tech Mono', monospace;
  --font-size-xs: 0.625rem;
  --font-size-sm: 0.75rem;
  --font-size-base: 0.875rem;
  --font-size-lg: 1rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 2rem;
  --font-size-hero: 3.5rem;

  /* Espaciado (escala de 4px) */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-12: 3rem;
  --space-16: 4rem;

  /* Efectos */
  --glow-cyan: 0 0 10px rgba(0, 245, 255, 0.5), 0 0 20px rgba(0, 245, 255, 0.2);
  --glow-magenta: 0 0 10px rgba(255, 0, 255, 0.5), 0 0 20px rgba(255, 0, 255, 0.2);
  --glow-yellow: 0 0 10px rgba(255, 215, 0, 0.5), 0 0 20px rgba(255, 215, 0, 0.2);
  --border-panel: 1px solid var(--color-border-subtle);
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
  --transition-fast: 150ms ease-out;
  --transition-base: 300ms ease-out;

  /* Layout */
  --sidebar-width: 320px;
  --header-height: 64px;
  --panel-padding: var(--space-6);
}

/* ============================================================
   RESET MÍNIMO
   ============================================================ */

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

img,
canvas {
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

* {
  font-family: inherit;
}

/* ============================================================
   PASO 2 — ESTILOS BASE DEL BODY Y TIPOGRAFÍA GLOBAL
   ============================================================ */

body {
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  line-height: 1.6;
  overflow-x: hidden;
  min-height: 100vh;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--color-text-primary);
  margin: 0;
}

h1 {
  font-size: var(--font-size-3xl);
}

h2 {
  font-size: var(--font-size-2xl);
}

h3 {
  font-size: var(--font-size-xl);
}

p {
  margin: 0;
  color: var(--color-text-secondary);
}

a {
  color: var(--color-accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-text-primary);
}

/* ============================================================
   PASO 3 — LAYOUT PRINCIPAL (APP SHELL)
   ============================================================ */

.app-shell {
  display: grid;
  grid-template-rows: var(--header-height) 1fr;
  grid-template-columns: 1fr var(--sidebar-width);
  grid-template-areas:
    "header header"
    "main   sidebar";
  min-height: 100vh;
}

.app-header {
  grid-area: header;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--space-8);
  background-color: var(--color-bg-secondary);
  border-bottom: var(--border-panel);
  position: sticky;
  top: 0;
  z-index: 100;
}

.app-main {
  grid-area: main;
  padding: var(--panel-padding);
  overflow-y: auto;
  background-color: var(--color-bg-primary);
}

.app-sidebar {
  grid-area: sidebar;
  background-color: var(--color-bg-panel);
  border-left: var(--border-panel);
  overflow-y: auto;
  padding: var(--panel-padding);
}

/* ============================================================
   PASO 4 — HEADER: LOGO Y CONTROLES
   ============================================================ */

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.header-logo__title {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
  margin: 0;
}

.header-logo__subtitle {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.header-controls {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.header-badge {
  font-size: var(--font-size-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-sm);
  padding: var(--space-1) var(--space-2);
}

/* ============================================================
   PASO 5 — COMPONENTE: PANEL / CARD
   ============================================================ */

.panel {
  background-color: var(--color-bg-panel);
  border: var(--border-panel);
  border-radius: var(--radius-md);
  padding: var(--panel-padding);
  position: relative;
  overflow: hidden;
}

.panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-cyan),
    transparent
  );
  opacity: 0.4;
}

.panel--accent-magenta::before {
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-magenta),
    transparent
  );
}

.panel--accent-yellow::before {
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-yellow),
    transparent
  );
}

.panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-4);
}

.panel__title {
  font-family: var(--font-display);
  font-size: var(--font-size-sm);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
}

.panel__status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--color-success);
  box-shadow: 0 0 6px var(--color-success);
  animation: pulse-dot 2s ease-in-out infinite;
}

.panel__status-dot--danger {
  background-color: var(--color-danger);
  box-shadow: 0 0 6px var(--color-danger);
}

/* ============================================================
   PASO 6 — COMPONENTE: KPI METRIC DISPLAY
   ============================================================ */

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-4);
  margin-bottom: var(--space-6);
}

.kpi-card {
  background-color: var(--color-bg-panel);
  border: var(--border-panel);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  position: relative;
  overflow: hidden;
  transition: border-color var(--transition-base);
}

.kpi-card:hover {
  border-color: var(--color-accent-cyan);
}

.kpi-card__label {
  font-size: var(--font-size-xs);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: var(--space-2);
}

.kpi-card__value {
  font-family: var(--font-display);
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
  line-height: 1.1;
}

.kpi-card__value--magenta {
  color: var(--color-accent-magenta);
  text-shadow: var(--glow-magenta);
}

.kpi-card__value--yellow {
  color: var(--color-accent-yellow);
  text-shadow: var(--glow-yellow);
}

.kpi-card__value--success {
  color: var(--color-success);
}

.kpi-card__value--danger {
  color: var(--color-danger);
}

.kpi-card__delta {
  font-size: var(--font-size-xs);
  margin-top: var(--space-1);
  color: var(--color-text-muted);
}

.kpi-card__delta--positive {
  color: var(--color-success);
}

.kpi-card__delta--negative {
  color: var(--color-danger);
}

.kpi-card__sparkline {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-cyan)
  );
  opacity: 0.3;
}

/* ============================================================
   PASO 7 — COMPONENTE: CANVAS VIEWPORT
   ============================================================ */

.canvas-viewport {
  position: relative;
  width: 100%;
  border: var(--border-panel);
  border-radius: var(--radius-md);
  overflow: hidden;
  background-color: var(--color-bg-secondary);
  margin-bottom: var(--space-6);
}

.canvas-viewport__layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.canvas-viewport__layer--base {
  position: relative;
}

.canvas-viewport__overlay {
  position: absolute;
  top: var(--space-4);
  left: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  pointer-events: none;
}

.canvas-viewport__label {
  font-size: var(--font-size-xs);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
  background-color: rgba(10, 10, 15, 0.7);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
  border: 1px solid rgba(0, 245, 255, 0.2);
}

/* ============================================================
   PASO 8 — COMPONENTE: BOTONES
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  font-family: var(--font-display);
  font-size: var(--font-size-sm);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  position: relative;
  overflow: hidden;
}

.btn--primary {
  background-color: var(--color-accent-cyan);
  color: var(--color-bg-primary);
  box-shadow: var(--glow-cyan);
}

.btn--primary:hover {
  background-color: var(--color-text-primary);
  box-shadow: 0 0 20px rgba(0, 245, 255, 0.8), 0 0 40px rgba(0, 245, 255, 0.4);
}

.btn--secondary {
  background-color: transparent;
  color: var(--color-accent-cyan);
  border: 1px solid var(--color-accent-cyan);
}

.btn--secondary:hover {
  background-color: rgba(0, 245, 255, 0.1);
  box-shadow: var(--glow-cyan);
}

.btn--danger {
  background-color: transparent;
  color: var(--color-danger);
  border: 1px solid var(--color-danger);
}

.btn--danger:hover {
  background-color: rgba(255, 51, 102, 0.1);
  box-shadow: 0 0 10px rgba(255, 51, 102, 0.5);
}

.btn--overdrive {
  background-color: var(--color-accent-magenta);
  color: var(--color-bg-primary);
  box-shadow: var(--glow-magenta);
  animation: overdrive-pulse 1.5s ease-in-out infinite;
}

.btn--overdrive:hover {
  background-color: var(--color-text-primary);
  box-shadow: 0 0 20px rgba(255, 0, 255, 0.8), 0 0 40px rgba(255, 0, 255, 0.4);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

/* ============================================================
   PASO 9 — COMPONENTE: TOGGLE SWITCH
   ============================================================ */

.toggle-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.toggle-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  background-color: var(--color-bg-secondary);
  border: var(--border-panel);
  border-radius: var(--radius-md);
  transition: border-color var(--transition-fast);
}

.toggle-item:hover {
  border-color: var(--color-accent-cyan);
}

.toggle-item__label {
  font-size: var(--font-size-sm);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
}

.toggle-item__description {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  margin-top: var(--space-1);
}

.toggle-switch {
  position: relative;
  width: 44px;
  height: 22px;
  flex-shrink: 0;
}

.toggle-switch__input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}

.toggle-switch__track {
  position: absolute;
  inset: 0;
  background-color: var(--color-bg-primary);
  border: 1px solid var(--color-border-subtle);
  border-radius: 11px;
  cursor: pointer;
  transition: background-color var(--transition-fast), border-color var(--transition-fast);
}

.toggle-switch__track::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: var(--color-text-muted);
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.toggle-switch__input:checked + .toggle-switch__track {
  background-color: rgba(0, 245, 255, 0.15);
  border-color: var(--color-accent-cyan);
}

.toggle-switch__input:checked + .toggle-switch__track::after {
  transform: translateX(22px);
  background-color: var(--color-accent-cyan);
  box-shadow: var(--glow-cyan);
}

/* ============================================================
   PASO 10 — COMPONENTE: PROGRESS BAR / GAUGE
   ============================================================ */

.gauge-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.gauge-item {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.gauge-item__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.gauge-item__label {
  font-size: var(--font-size-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
}

.gauge-item__value {
  font-family: var(--font-display);
  font-size: var(--font-size-sm);
  color: var(--color-accent-cyan);
}

.gauge-track {
  width: 100%;
  height: 4px;
  background-color: var(--color-bg-secondary);
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--color-border-subtle);
}

.gauge-fill {
  height: 100%;
  background: linear-gradient(
    90deg,
    var(--color-accent-cyan),
    rgba(0, 245, 255, 0.6)
  );
  border-radius: var(--radius-sm);
  transition: width var(--transition-base);
  box-shadow: var(--glow-cyan);
}

.gauge-fill--magenta {
  background: linear-gradient(
    90deg,
    var(--color-accent-magenta),
    rgba(255, 0, 255, 0.6)
  );
  box-shadow: var(--glow-magenta);
}

.gauge-fill--yellow {
  background: linear-gradient(
    90deg,
    var(--color-accent-yellow),
    rgba(255, 215, 0, 0.6)
  );
  box-shadow: var(--glow-yellow);
}

.gauge-fill--danger {
  background: linear-gradient(
    90deg,
    var(--color-danger),
    rgba(255, 51, 102, 0.6)
  );
}

/* ============================================================
   PASO 11 — COMPONENTE: SIDEBAR SECTIONS
   ============================================================ */

.sidebar-section {
  margin-bottom: var(--space-6);
}

.sidebar-section:last-child {
  margin-bottom: 0;
}

.sidebar-section__title {
  font-family: var(--font-display);
  font-size: var(--font-size-xs);
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: var(--border-panel);
}

.sidebar-divider {
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-border-subtle),
    transparent
  );
  margin: var(--space-6) 0;
}

/* ============================================================
   PASO 12 — COMPONENTE: LOG / FEED DE EVENTOS
   ============================================================ */

.event-log {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  max-height: 200px;
  overflow-y: auto;
}

.event-log__entry {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--space-2);
  font-size: var(--font-size-xs);
  line-height: 1.4;
  padding: var(--space-2);
  border-radius: var(--radius-sm);
  background-color: var(--color-bg-secondary);
  border-left: 2px solid var(--color-border-subtle);
  animation: entry-slide-in 200ms ease-out;
}

.event-log__entry--info {
  border-left-color: var(--color-accent-cyan);
}

.event-log__entry--warning {
  border-left-color: var(--color-accent-yellow);
}

.event-log__entry--danger {
  border-left-color: var(--color-danger);
}

.event-log__entry--success {
  border-left-color: var(--color-success);
}

.event-log__timestamp {
  color: var(--color-text-muted);
  white-space: nowrap;
  font-size: var(--font-size-xs);
}

.event-log__message {
  color: var(--color-text-secondary);
}

/* ============================================================
   PASO 13 — ESTADOS GLOBALES Y MODIFICADORES
   ============================================================ */

.is-active {
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
}

.is-danger {
  color: var(--color-danger);
}

.is-success {
  color: var(--color-success);
}

.is-muted {
  color: var(--color-text-muted);
}

.is-hidden {
  display: none !important;
}

.is-overdrive .app-header {
  border-bottom-color: var(--color-accent-magenta);
  box-shadow: 0 1px 0 0 rgba(255, 0, 255, 0.3);
}

.is-overdrive .panel::before {
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-magenta),
    transparent
  );
  opacity: 0.7;
}

.is-overdrive .kpi-card__value {
  color: var(--color-accent-magenta);
  text-shadow: var(--glow-magenta);
}

/* ============================================================
   PASO 14 — ANIMACIONES (@keyframes)
   ============================================================ */

@keyframes pulse-dot {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.7);
  }
}

@keyframes overdrive-pulse {
  0%, 100% {
    box-shadow: var(--glow-magenta);
  }
  50% {
    box-shadow: 0 0 20px rgba(255, 0, 255, 0.8), 0 0 40px rgba(255, 0, 255, 0.5);
  }
}

@keyframes entry-slide-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes glow-flicker {
  0%, 100% {
    opacity: 1;
  }
  92% {
    opacity: 1;
  }
  93% {
    opacity: 0.6;
  }
  94% {
    opacity: 1;
  }
  96% {
    opacity: 0.7;
  }
  97% {
    opacity: 1;
  }
}

@keyframes scan-line {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(100vh);
  }
}

@keyframes data-stream {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

/* ============================================================
   PASO 15 — EFECTOS DECORATIVOS GLOBALES
   ============================================================ */

.scanline-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 9999;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.03) 2px,
    rgba(0, 0, 0, 0.03) 4px
  );
}

.glow-text--cyan {
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
  animation: glow-flicker 8s ease-in-out infinite;
}

.glow-text--magenta {
  color: var(--color-accent-magenta);
  text-shadow: var(--glow-magenta);
  animation: glow-flicker 6s ease-in-out infinite;
}

.glow-text--yellow {
  color: var(--color-accent-yellow);
  text-shadow: var(--glow-yellow);
}

.data-stream-bar {
  height: 2px;
  background: linear-gradient(
    270deg,
    var(--color-accent-cyan),
    var(--color-accent-magenta),
    var(--color-accent-cyan)
  );
  background-size: 200% 200%;
  animation: data-stream 3s ease infinite;
}

/* ============================================================
   PASO 16 — SCROLLBAR PERSONALIZADA
   ============================================================ */

::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}

::-webkit-scrollbar-track {
  background: var(--color-bg-primary);
}

::-webkit-scrollbar-thumb {
  background: var(--color-border-subtle);
  border-radius: var(--radius-sm);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--color-text-muted);
}

* {
  scrollbar-width: thin;
  scrollbar-color: var(--color-border-subtle) var(--color-bg-primary);
}

/* ============================================================
   PASO 17 — RESPONSIVE (BREAKPOINT ÚNICO)
   ============================================================ */

@media (max-width: 900px) {
  .app-shell {
    grid-template-columns: 1fr;
    grid-template-rows: var(--header-height) 1fr auto;
    grid-template-areas:
      "header"
      "main"
      "sidebar";
  }

  .app-sidebar {
    border-left: none;
    border-top: var(--border-panel);
  }

  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .header-logo__subtitle {
    display: none;
  }
}

@media (max-width: 480px) {
  .kpi-grid {
    grid-template-columns: 1fr;
  }

  .header-logo__title {
    font-size: var(--font-size-lg);
  }

  .app-main {
    padding: var(--space-4);
  }

  .app-sidebar {
    padding: var(--space-4);
  }
}

/* === KPI CARDS === */

.pg-kpi-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
  position: relative;
  cursor: default;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.pg-kpi-card.is-active {
  border-color: var(--color-accent-primary);
  box-shadow: 0 0 12px var(--color-accent-glow);
}

.pg-kpi-card::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--color-accent-primary);
  border-radius: var(--radius-md) 0 0 var(--radius-md);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.pg-kpi-card.is-active::before {
  opacity: 1;
}

.pg-kpi-card__label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.pg-kpi-card__value {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.pg-kpi-card__delta {
  font-size: var(--font-size-sm);
  display: flex;
  align-items: center;
  gap: 4px;
}

.pg-kpi-card__delta.is-positive {
  color: var(--color-success);
}

.pg-kpi-card__delta.is-negative {
  color: var(--color-danger);
}

/* === TOGGLE SWITCHES === */

.pg-toggle {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  cursor: pointer;
  user-select: none;
}

.pg-toggle__input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.pg-toggle__track {
  width: 40px;
  height: 22px;
  background: var(--color-border);
  border-radius: 11px;
  position: relative;
  transition: background 0.2s ease;
  flex-shrink: 0;
}

.pg-toggle__input:checked + .pg-toggle__track {
  background: var(--color-accent-primary);
}

.pg-toggle__track::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  background: var(--color-text-primary);
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.pg-toggle__input:checked + .pg-toggle__track::after {
  transform: translateX(18px);
}

.pg-toggle__input:focus-visible + .pg-toggle__track {
  outline: 2px solid var(--color-accent-primary);
  outline-offset: 2px;
}

.pg-toggle__label {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
}

.pg-toggle.is-disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

/* === SLIDERS === */

.pg-slider {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.pg-slider__header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.pg-slider__label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.pg-slider__value {
  font-size: var(--font-size-sm);
  font-weight: 700;
  color: var(--color-accent-primary);
  font-variant-numeric: tabular-nums;
}

.pg-slider__input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 4px;
  background: var(--color-border);
  border-radius: 2px;
  outline: none;
  cursor: pointer;
}

.pg-slider__input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--color-accent-primary);
  box-shadow: 0 0 6px var(--color-accent-glow);
  transition: box-shadow 0.2s ease;
}

.pg-slider__input::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: var(--color-accent-primary);
  box-shadow: 0 0 6px var(--color-accent-glow);
  cursor: pointer;
  transition: box-shadow 0.2s ease;
}

.pg-slider__input:hover::-webkit-slider-thumb {
  box-shadow: 0 0 12px var(--color-accent-glow);
}

.pg-slider__input:hover::-moz-range-thumb {
  box-shadow: 0 0 12px var(--color-accent-glow);
}

.pg-slider__input:focus-visible {
  outline: 2px solid var(--color-accent-primary);
  outline-offset: 4px;
  border-radius: 2px;
}

/* === SIDE PANEL === */

.pg-side-panel {
  background: var(--color-surface);
  border-left: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: width 0.3s ease, opacity 0.3s ease;
}

.pg-side-panel.is-collapsed {
  width: 0;
  opacity: 0;
  pointer-events: none;
}

.pg-side-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

.pg-side-panel__title {
  font-size: var(--font-size-sm);
  font-weight: 700;
  color: var(--color-text-primary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.pg-side-panel__close {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  transition: color 0.2s ease, background 0.2s ease;
}

.pg-side-panel__close:hover {
  color: var(--color-text-primary);
  background: var(--color-border);
}

.pg-side-panel__body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.pg-side-panel__body::-webkit-scrollbar {
  width: 4px;
}

.pg-side-panel__body::-webkit-scrollbar-track {
  background: transparent;
}

.pg-side-panel__body::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 2px;
}

.pg-side-panel__section {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.pg-side-panel__section-title {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding-bottom: var(--spacing-xs);
  border-bottom: 1px solid var(--color-border);
}

/* === OVERLAYS === */

.pg-overlay {
  position: fixed;
  inset: 0;
  background: var(--color-overlay-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  z-index: var(--z-overlay);
}

.pg-overlay.is-visible {
  opacity: 1;
  pointer-events: auto;
}

.pg-overlay__dialog {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  max-width: 480px;
  width: 90%;
  transform: translateY(8px);
  transition: transform 0.25s ease;
}

.pg-overlay.is-visible .pg-overlay__dialog {
  transform: translateY(0);
}

.pg-overlay__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pg-overlay__title {
  font-size: var(--font-size-md);
  font-weight: 700;
  color: var(--color-text-primary);
}

.pg-overlay__close {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  transition: color 0.2s ease, background 0.2s ease;
}

.pg-overlay__close:hover {
  color: var(--color-text-primary);
  background: var(--color-border);
}

.pg-overlay__body {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.pg-overlay__footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--spacing-sm);
}

/* === BUTTONS === */

.pg-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-xs);
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease;
  user-select: none;
  white-space: nowrap;
}

.pg-btn--primary {
  background: var(--color-accent-primary);
  color: var(--color-bg);
  border-color: var(--color-accent-primary);
}

.pg-btn--primary:hover {
  box-shadow: 0 0 10px var(--color-accent-glow);
}

.pg-btn--ghost {
  background: transparent;
  color: var(--color-text-secondary);
  border-color: var(--color-border);
}

.pg-btn--ghost:hover {
  color: var(--color-text-primary);
  border-color: var(--color-text-muted);
  background: var(--color-border);
}

.pg-btn--danger {
  background: transparent;
  color: var(--color-danger);
  border-color: var(--color-danger);
}

.pg-btn--danger:hover {
  background: var(--color-danger);
  color: var(--color-bg);
}

.pg-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

/* === STATUS BADGE === */

.pg-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.pg-badge--active {
  background: color-mix(in srgb, var(--color-success) 15%, transparent);
  color: var(--color-success);
}

.pg-badge--inactive {
  background: color-mix(in srgb, var(--color-text-muted) 15%, transparent);
  color: var(--color-text-muted);
}

.pg-badge--warning {
  background: color-mix(in srgb, var(--color-warning) 15%, transparent);
  color: var(--color-warning);
}

.pg-badge--danger {
  background: color-mix(in srgb, var(--color-danger) 15%, transparent);
  color: var(--color-danger);
}

.pg-badge__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

/* === DIVIDER === */

.pg-divider {
  height: 1px;
  background: var(--color-border);
  border: none;
  margin: 0;
}

.pg-divider--vertical {
  width: 1px;
  height: auto;
  align-self: stretch;
}

/* === TOOLTIP === */

.pg-tooltip-wrapper {
  position: relative;
  display: inline-flex;
}

.pg-tooltip-wrapper:hover .pg-tooltip,
.pg-tooltip-wrapper:focus-within .pg-tooltip {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.pg-tooltip {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 4px 8px;
  font-size: var(--font-size-xs);
  color: var(--color-text-primary);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease, transform 0.15s ease;
  z-index: var(--z-tooltip);
}

/* === OVERDRIVE INDICATOR === */

.pg-overdrive-indicator {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-accent-secondary);
  background: color-mix(in srgb, var(--color-accent-secondary) 10%, transparent);
  font-size: var(--font-size-xs);
  font-weight: 700;
  color: var(--color-accent-secondary);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  transition: opacity 0.3s ease;
}

.pg-overdrive-indicator.is-hidden {
  opacity: 0;
  pointer-events: none;
}

.pg-overdrive-indicator__pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent-secondary);
  flex-shrink: 0;
}

@media (max-width: 600px) {
  .pg-kpi-card {
    padding: var(--spacing-sm);
  }

  .pg-side-panel__body {
    padding: var(--spacing-sm);
  }

  .pg-overlay__dialog {
    padding: var(--spacing-md);
  }

  .pg-btn {
    padding: var(--spacing-xs) var(--spacing-sm);
  }
}

/* ==========================================================================
   animations.css
   Propósito: Define exclusivamente @keyframes y clases utilitarias de animación
   para el proyecto "The Power Grid" Dashboard.

   Consumido por: main.css, panels.css, components.css

   ADVERTENCIA: No agregar selectores de layout, variables de color ni
   propiedades de transición en este archivo. Solo @keyframes y sus
   clases de aplicación directa.
   ========================================================================== */


/* ==========================================================================
   PASO 2 — Parpadeo eléctrico (Flicker)
   ========================================================================== */

@keyframes glx-flicker {
  0%   { opacity: 1; }
  8%   { opacity: 0.85; }
  15%  { opacity: 1; }
  22%  { opacity: 0.4; }
  24%  { opacity: 0.1; }
  26%  { opacity: 0.95; }
  40%  { opacity: 1; }
  55%  { opacity: 0.85; }
  57%  { opacity: 0.4; }
  59%  { opacity: 1; }
  75%  { opacity: 0.95; }
  88%  { opacity: 0.4; }
  90%  { opacity: 0.1; }
  92%  { opacity: 1; }
  100% { opacity: 0.95; }
}

.anim-flicker {
  animation-name: glx-flicker;
  animation-duration: var(--duration-flicker);
  animation-timing-function: steps(1, end);
  animation-iteration-count: infinite;
  animation-fill-mode: both;
}


/* ==========================================================================
   PASO 3 — Pulso de borde energético (Pulse Border)
   ========================================================================== */

@keyframes glx-pulse-border {
  0% {
    box-shadow:
      0 0 0px 0px var(--color-accent-primary),
      0 0 0px 0px var(--color-accent-secondary);
  }
  50% {
    box-shadow:
      0 0 6px 4px var(--color-accent-primary),
      0 0 10px 8px var(--color-accent-secondary);
  }
  100% {
    box-shadow:
      0 0 0px 0px var(--color-accent-primary),
      0 0 0px 0px var(--color-accent-secondary);
  }
}

.anim-pulse-border {
  animation-name: glx-pulse-border;
  animation-duration: var(--duration-pulse);
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
  animation-direction: alternate;
}


/* ==========================================================================
   PASO 4 — Línea de escaneo horizontal (Scan Line)
   ========================================================================== */

@keyframes glx-scan-line {
  0%   { transform: translateY(-100%); }
  100% { transform: translateY(100vh); }
}

.anim-scan-line {
  animation-name: glx-scan-line;
  animation-duration: var(--duration-scan);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-fill-mode: none;
}


/* ==========================================================================
   PASO 5 — Arranque de panel tipo terminal (Panel Boot)
   ========================================================================== */

@keyframes glx-panel-boot {
  0% {
    opacity: 0;
    clip-path: inset(0 100% 0 0);
  }
  30% {
    opacity: 1;
    clip-path: inset(0 40% 0 0);
  }
  70% {
    opacity: 1;
    clip-path: inset(0 10% 0 0);
  }
  100% {
    opacity: 1;
    clip-path: inset(0 0% 0 0);
  }
}

.anim-panel-boot {
  animation-name: glx-panel-boot;
  animation-duration: var(--duration-panel-boot);
  animation-timing-function: ease-out;
  animation-iteration-count: 1;
  animation-fill-mode: both;
}

const _DEFAULT_STATE = {
  teamSize:        5,
  avgSalary:       75000,
  automationLevel: 3,
  overdriveActive: false,
  aiAssistActive:  false,
  deepScanActive:  false,
};

const _state = { ..._DEFAULT_STATE };

const _clamp = (value, min, max) => Math.min(Math.max(value, min), max);

export function getState() {
  return { ..._state };
}

export function setState(patch) {
  Object.keys(patch).forEach((key) => {
    if (!(key in _state)) return;

    if (key === 'teamSize') {
      _state[key] = _clamp(patch[key], 1, 50);
    } else if (key === 'avgSalary') {
      _state[key] = _clamp(patch[key], 30000, 200000);
    } else if (key === 'automationLevel') {
      _state[key] = _clamp(patch[key], 1, 10);
    } else {
      _state[key] = Boolean(patch[key]);
    }
  });
}

export function resetState() {
  Object.assign(_state, { ..._DEFAULT_STATE });
}

export function getToggleStates() {
  return {
    overdriveActive: _state.overdriveActive,
    aiAssistActive:  _state.aiAssistActive,
    deepScanActive:  _state.deepScanActive,
  };
}

/**
 * @fileoverview KPI Engine - Motor de cálculo puro de métricas de negocio.
 * Transforma el estado global y KPI_CONFIG en métricas numéricas formateadas.
 * Sin efectos secundarios. Sin acceso al DOM. Sin dependencias externas.
 */

// =============================================================================
// SECCIÓN 1: CONFIGURACIÓN ESTÁTICA (NO EXPORTADA)
// =============================================================================

const KPI_CONFIG = {
  baseRevenue:          2_400_000,
  baseChurnRate:        0.045,
  baseNPS:              32,
  baseResolutionTime:   48,
  baseAgentUtilization: 0.71,
  baseTicketVolume:     1200,

  multipliers: {
    aiAssist: {
      revenue:        1.18,
      churn:          0.82,
      nps:            1.22,
      resolutionTime: 0.65
    },
    omnichannel: {
      revenue:          1.12,
      agentUtilization: 1.15,
      ticketVolume:     1.20
    },
    analytics: {
      revenue: 1.09,
      nps:     1.14,
      churn:   0.88
    },
    automation: {
      resolutionTime:   0.50,
      agentUtilization: 0.85,
      ticketVolume:     0.70
    },
    selfService: {
      ticketVolume:   0.60,
      resolutionTime: 0.75
    },
    overdrive: {
      revenue: 1.25,
      nps:     1.30
    }
  }
};

// =============================================================================
// SECCIÓN 2: FUNCIONES PRIVADAS (NO EXPORTADAS)
// =============================================================================

/**
 * Aplica una lista de multiplicadores a un valor base.
 * @param {number} baseValue - Valor base sobre el que se opera.
 * @param {number[]} multipliersList - Array de factores activos para este KPI.
 * @param {'multiply'|'add'} operation - Tipo de operación a aplicar.
 * @returns {number} Valor resultante tras aplicar todos los factores.
 */
function _applyMultipliers(baseValue, multipliersList, operation) {
  if (multipliersList.length === 0) {
    return baseValue;
  }

  if (operation === 'multiply') {
    return multipliersList.reduce((acc, factor) => acc * factor, baseValue);
  }

  if (operation === 'add') {
    return multipliersList.reduce((acc, factor) => acc + factor, baseValue);
  }

  return baseValue;
}

/**
 * Recopila los factores activos de KPI_CONFIG.multipliers según el estado actual.
 * @param {Object} state - Estado global de la aplicación (no se muta).
 * @param {string} kpiKey - Clave del KPI a buscar en cada bloque de multiplicadores.
 * @returns {number[]} Array de factores numéricos activos para el KPI dado.
 */
function _collectActiveMultipliers(state, kpiKey) {
  const activeFactors = [];

  for (const [featureKey, multiplierBlock] of Object.entries(KPI_CONFIG.multipliers)) {
    if (state[featureKey] === true && multiplierBlock[kpiKey] !== undefined) {
      activeFactors.push(multiplierBlock[kpiKey]);
    }
  }

  return activeFactors;
}

/**
 * Formatea un valor numérico como cadena de moneda abreviada.
 * @param {number} value - Valor monetario a formatear.
 * @returns {string} Cadena formateada (ej. "$3.8M", "$842.5k", "$320").
 */
function _formatCurrency(value) {
  if (value >= 1_000_000) {
    return `$${(value / 1_000_000).toFixed(1)}M`;
  }
  if (value >= 1_000) {
    return `$${(value / 1_000).toFixed(1)}k`;
  }
  return `$${Math.round(value)}`;
}

/**
 * Calcula y formatea el delta entre un valor actual y su base de referencia.
 * @param {number} currentValue - Valor calculado con los multiplicadores activos.
 * @param {number} baseValue - Valor base sin modificadores.
 * @param {string} unit - Unidad de medida para el texto del delta (ej. '%', 'h', 'pts').
 * @param {boolean} higherIsBetter - true si un valor mayor es favorable para el negocio.
 * @returns {{ text: string, positive: boolean|null }} Objeto con texto formateado e indicador de mejora.
 */
function _formatDelta(currentValue, baseValue, unit, higherIsBetter) {
  const delta = currentValue - baseValue;
  const deltaPercent = (delta / baseValue) * 100;

  if (delta === 0) {
    return { text: '—', positive: null };
  }

  const sign = delta > 0 ? '+' : '';
  const positive = higherIsBetter ? delta > 0 : delta < 0;

  let text;
  if (unit === '%') {
    text = `${sign}${deltaPercent.toFixed(1)}%`;
  } else {
    text = `${sign}${delta.toFixed(1)} ${unit}`;
  }

  return { text, positive };
}

// =============================================================================
// SECCIÓN 3: FUNCIONES EXPORTADAS — CÁLCULO DE KPIs
// =============================================================================

/**
 * Calcula el KPI de Revenue (Ingresos Anuales).
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{ value: string, delta: { text: string, positive: boolean|null }, raw: number }}
 */
export function calculateRevenue(state) {
  const factors = _collectActiveMultipliers(state, 'revenue');
  const raw = _applyMultipliers(KPI_CONFIG.baseRevenue, factors, 'multiply');

  return {
    value: _formatCurrency(raw),
    delta: _formatDelta(raw, KPI_CONFIG.baseRevenue, '%', true),
    raw
  };
}

/**
 * Calcula el KPI de Churn Rate (Tasa de Abandono de Clientes).
 * Un valor menor es mejor para el negocio.
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{ value: string, delta: { text: string, positive: boolean|null }, raw: number }}
 */
export function calculateChurnRate(state) {
  const factors = _collectActiveMultipliers(state, 'churn');
  const raw = _applyMultipliers(KPI_CONFIG.baseChurnRate, factors, 'multiply');
  const displayValue = `${(raw * 100).toFixed(2)}%`;

  return {
    value: displayValue,
    delta: _formatDelta(raw * 100, KPI_CONFIG.baseChurnRate * 100, '%', false),
    raw
  };
}

/**
 * Calcula el KPI de NPS (Net Promoter Score).
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{ value: string, delta: { text: string, positive: boolean|null }, raw: number }}
 */
export function calculateNPS(state) {
  const factors = _collectActiveMultipliers(state, 'nps');
  const raw = _applyMultipliers(KPI_CONFIG.baseNPS, factors, 'multiply');
  const rounded = Math.round(raw);

  return {
    value: `${rounded}`,
    delta: _formatDelta(rounded, KPI_CONFIG.baseNPS, 'pts', true),
    raw: rounded
  };
}

/**
 * Calcula el KPI de Resolution Time (Tiempo Medio de Resolución de Tickets).
 * Un valor menor es mejor para el negocio.
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{ value: string, delta: { text: string, positive: boolean|null }, raw: number }}
 */
export function calculateResolutionTime(state) {
  const factors = _collectActiveMultipliers(state, 'resolutionTime');
  const raw = _applyMultipliers(KPI_CONFIG.baseResolutionTime, factors, 'multiply');
  const rounded = Math.round(raw);

  return {
    value: `${rounded}h`,
    delta: _formatDelta(rounded, KPI_CONFIG.baseResolutionTime, 'h', false),
    raw: rounded
  };
}

/**
 * Calcula el KPI de Agent Utilization (Utilización de Agentes).
 * Un valor mayor indica mayor eficiencia operativa y es favorable para el negocio.
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{ value: string, delta: { text: string, positive: boolean|null }, raw: number }}
 */
export function calculateAgentUtilization(state) {
  const factors = _collectActiveMultipliers(state, 'agentUtilization');
  const raw = _applyMultipliers(KPI_CONFIG.baseAgentUtilization, factors, 'multiply');
  const capped = Math.min(raw, 1.0);
  const displayValue = `${(capped * 100).toFixed(1)}%`;

  return {
    value: displayValue,
    delta: _formatDelta(capped * 100, KPI_CONFIG.baseAgentUtilization * 100, '%', true),
    raw: capped
  };
}

/**
 * Calcula el KPI de Ticket Volume (Volumen de Tickets Entrantes).
 * Un valor menor indica mayor deflexión y es favorable para el negocio.
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{ value: string, delta: { text: string, positive: boolean|null }, raw: number }}
 */
export function calculateTicketVolume(state) {
  const factors = _collectActiveMultipliers(state, 'ticketVolume');
  const raw = _applyMultipliers(KPI_CONFIG.baseTicketVolume, factors, 'multiply');
  const rounded = Math.round(raw);

  return {
    value: `${rounded.toLocaleString('en-US')}`,
    delta: _formatDelta(rounded, KPI_CONFIG.baseTicketVolume, 'tickets', false),
    raw: rounded
  };
}

/**
 * Ejecuta todos los cálculos de KPI en una sola llamada.
 * Punto de entrada principal para el renderer.
 * @param {Object} state - Estado global de la aplicación.
 * @returns {{
 *   revenue:          ReturnType<typeof calculateRevenue>,
 *   churnRate:        ReturnType<typeof calculateChurnRate>,
 *   nps:              ReturnType<typeof calculateNPS>,
 *   resolutionTime:   ReturnType<typeof calculateResolutionTime>,
 *   agentUtilization: ReturnType<typeof calculateAgentUtilization>,
 *   ticketVolume:     ReturnType<typeof calculateTicketVolume>
 * }}
 */
export function computeAllKPIs(state) {
  return {
    revenue:          calculateRevenue(state),
    churnRate:        calculateChurnRate(state),
    nps:              calculateNPS(state),
    resolutionTime:   calculateResolutionTime(state),
    agentUtilization: calculateAgentUtilization(state),
    ticketVolume:     calculateTicketVolume(state)
  };
}

// =============================================================================
// canvas-engine.js
// Motor de renderizado de partículas y conexiones (Canvas 2D puro).
// Responsabilidad única: recibir estado externo, dibujar, no decidir negocio.
// =============================================================================

// -----------------------------------------------------------------------------
// PASO 1 — Constantes visuales privadas (no exportadas)
// -----------------------------------------------------------------------------
const PARTICLE_COUNT_BASE       = 80;
const PARTICLE_COUNT_OVERDRIVE  = 150;
const CONNECTION_DISTANCE       = 120;
const PARTICLE_SPEED_BASE       = 0.4;
const PARTICLE_SPEED_OVERDRIVE  = 1.1;
const PARTICLE_RADIUS_MIN       = 1;
const PARTICLE_RADIUS_MAX       = 3;
const COLOR_PARTICLE_NORMAL     = '#00f0ff';
const COLOR_PARTICLE_OVERDRIVE  = '#ff00ff';
const COLOR_CONNECTION          = 'rgba(0, 240, 255, 0.15)';
const COLOR_CONNECTION_OVERDRIVE = 'rgba(255, 0, 255, 0.2)';
const COLOR_BG_CLEAR            = 'rgba(10, 10, 20, 0.15)';

// -----------------------------------------------------------------------------
// PASO 2 — Estado interno privado del módulo (única fuente de verdad interna)
// -----------------------------------------------------------------------------
const _state = {
  particleCanvas:    null,
  connectionCanvas:  null,
  pCtx:              null,
  cCtx:              null,
  particles:         [],
  animationId:       null,
  isOverdriveActive: false,
  isRunning:         false
};

// -----------------------------------------------------------------------------
// PASO 3 — Función auxiliar privada: _createParticle(width, height)
// Retorna un objeto literal que representa una partícula.
// -----------------------------------------------------------------------------
function _createParticle(width, height) {
  const speed = _state.isOverdriveActive ? PARTICLE_SPEED_OVERDRIVE : PARTICLE_SPEED_BASE;
  return {
    x:      Math.random() * width,
    y:      Math.random() * height,
    vx:     (Math.random() * 2 - 1) * speed,
    vy:     (Math.random() * 2 - 1) * speed,
    radius: PARTICLE_RADIUS_MIN + Math.random() * (PARTICLE_RADIUS_MAX - PARTICLE_RADIUS_MIN)
  };
}

// -----------------------------------------------------------------------------
// PASO 4 — Función auxiliar privada: _initParticles()
// Vacía y rellena _state.particles según el modo activo.
// -----------------------------------------------------------------------------
function _initParticles() {
  const width  = _state.particleCanvas.width;
  const height = _state.particleCanvas.height;
  const count  = _state.isOverdriveActive ? PARTICLE_COUNT_OVERDRIVE : PARTICLE_COUNT_BASE;

  _state.particles = [];
  for (let i = 0; i < count; i++) {
    _state.particles.push(_createParticle(width, height));
  }
}

// -----------------------------------------------------------------------------
// PASO 5 — Función auxiliar privada: _drawFrame()
// Cuerpo del loop de animación. Orden de sub-pasos es estricto.
// -----------------------------------------------------------------------------
function _drawFrame() {
  const { pCtx, cCtx, particles, isOverdriveActive } = _state;
  const width  = _state.particleCanvas.width;
  const height = _state.particleCanvas.height;

  // 5a — Limpiar canvas
  // Partículas: efecto trail con rectángulo semitransparente (NO clearRect puro)
  pCtx.fillStyle = COLOR_BG_CLEAR;
  pCtx.fillRect(0, 0, width, height);

  // Conexiones: limpieza total cada frame (sin trail en conexiones)
  cCtx.clearRect(0, 0, width, height);

  // Colores según modo
  const particleColor    = isOverdriveActive ? COLOR_PARTICLE_OVERDRIVE  : COLOR_PARTICLE_NORMAL;
  const connectionColor  = isOverdriveActive ? COLOR_CONNECTION_OVERDRIVE : COLOR_CONNECTION;

  // 5b — Actualizar posición y rebotar en bordes
  for (let i = 0; i < particles.length; i++) {
    const p = particles[i];

    p.x += p.vx;
    p.y += p.vy;

    // Rebote en borde izquierdo / derecho
    if (p.x - p.radius < 0) {
      p.x  = p.radius;
      p.vx = Math.abs(p.vx);
    } else if (p.x + p.radius > width) {
      p.x  = width - p.radius;
      p.vx = -Math.abs(p.vx);
    }

    // Rebote en borde superior / inferior
    if (p.y - p.radius < 0) {
      p.y  = p.radius;
      p.vy = Math.abs(p.vy);
    } else if (p.y + p.radius > height) {
      p.y  = height - p.radius;
      p.vy = -Math.abs(p.vy);
    }
  }

  // 5c — Dibujar conexiones entre partículas próximas (canvas de conexiones)
  cCtx.strokeStyle = connectionColor;
  cCtx.lineWidth   = 0.6;

  for (let i = 0; i < particles.length; i++) {
    for (let j = i + 1; j < particles.length; j++) {
      const dx   = particles[i].x - particles[j].x;
      const dy   = particles[i].y - particles[j].y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < CONNECTION_DISTANCE) {
        // Opacidad proporcional a la proximidad
        const alpha = 1 - dist / CONNECTION_DISTANCE;
        cCtx.globalAlpha = alpha;
        cCtx.beginPath();
        cCtx.moveTo(particles[i].x, particles[i].y);
        cCtx.lineTo(particles[j].x, particles[j].y);
        cCtx.stroke();
      }
    }
  }
  // Restaurar globalAlpha para no contaminar otros dibujos
  cCtx.globalAlpha = 1;

  // 5d — Dibujar partículas (canvas de partículas)
  pCtx.fillStyle = particleColor;

  for (let i = 0; i < particles.length; i++) {
    const p = particles[i];
    pCtx.beginPath();
    pCtx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    pCtx.fill();
  }

  // 5e — Encolar el siguiente frame
  _state.animationId = requestAnimationFrame(_drawFrame);
}

// =============================================================================
// API PÚBLICA EXPORTADA
// =============================================================================

/**
 * Inicializa el motor de canvas.
 * Debe llamarse una única vez antes de `startEngine`.
 *
 * @param {HTMLCanvasElement} particleCanvas  - Canvas destinado a las partículas.
 * @param {HTMLCanvasElement} connectionCanvas - Canvas destinado a las conexiones.
 */
export function initEngine(particleCanvas, connectionCanvas) {
  _state.particleCanvas   = particleCanvas;
  _state.connectionCanvas = connectionCanvas;
  _state.pCtx             = particleCanvas.getContext('2d');
  _state.cCtx             = connectionCanvas.getContext('2d');
}

/**
 * Arranca el loop de animación.
 * Incluye guardia contra doble arranque.
 */
export function startEngine() {
  if (_state.isRunning) return;
  _state.isRunning = true;
  _initParticles();
  _state.animationId = requestAnimationFrame(_drawFrame);
}

/**
 * Detiene el loop de animación y limpia ambos canvas.
 */
export function stopEngine() {
  if (_state.animationId !== null) {
    cancelAnimationFrame(_state.animationId);
    _state.animationId = null;
  }
  _state.isRunning = false;

  if (_state.pCtx) {
    _state.pCtx.clearRect(
      0, 0,
      _state.particleCanvas.width,
      _state.particleCanvas.height
    );
  }
  if (_state.cCtx) {
    _state.cCtx.clearRect(
      0, 0,
      _state.connectionCanvas.width,
      _state.connectionCanvas.height
    );
  }
}

/**
 * Activa o desactiva el modo Overdrive.
 * Reinicia el pool de partículas con la nueva cantidad y velocidad.
 *
 * @param {boolean} active - `true` para activar Overdrive, `false` para modo normal.
 */
export function setOverdriveMode(active) {
  if (_state.isOverdriveActive === active) return;
  _state.isOverdriveActive = active;

  // Reiniciar partículas con nueva velocidad y cantidad
  if (_state.isRunning) {
    _initParticles();
  }
}

/**
 * Redimensiona ambos canvas al tamaño del contenedor y reinicia las partículas.
 * Debe llamarse desde el listener `resize` del ui-controller.
 *
 * @param {number} width  - Nuevo ancho en píxeles.
 * @param {number} height - Nuevo alto en píxeles.
 */
export function resizeEngine(width, height) {
  if (!_state.particleCanvas || !_state.connectionCanvas) return;

  _state.particleCanvas.width    = width;
  _state.particleCanvas.height   = height;
  _state.connectionCanvas.width  = width;
  _state.connectionCanvas.height = height;

  if (_state.isRunning) {
    _initParticles();
  }
}

/**
 * @fileoverview ui-controller.js
 * Orquestador de eventos DOM. Escucha acciones del usuario y delega al estado y callbacks.
 * No calcula, no renderiza: solo escucha y delega.
 */

// ─── Cache de nodos DOM (se popula una sola vez en _cacheNodes) ───────────────
const _nodes = {
  overdriveToggle: null,
  resetBtn: null,
  sliders: {
    dealSize: { input: null, display: null },
    winRate:  { input: null, display: null },
    cycle:    { input: null, display: null }
  },
  kpiToggles: null
};

// ─── Mapa de sliders: clave interna → IDs del DOM ────────────────────────────
const _SLIDER_MAP = {
  dealSize: { inputId: '#slider-deal-size',       displayId: '#slider-deal-size-value' },
  winRate:  { inputId: '#slider-win-rate',        displayId: '#slider-win-rate-value'  },
  cycle:    { inputId: '#slider-cycle',           displayId: '#slider-cycle-value'     }
};

// ─── PASO 3: _cacheNodes ──────────────────────────────────────────────────────
/**
 * Popula _nodes con referencias a los elementos del DOM.
 * Emite console.warn por cada nodo faltante; nunca lanza Error.
 * @private
 */
function _cacheNodes() {
  // Nodos simples
  const simpleMap = {
    overdriveToggle: '#overdrive-toggle',
    resetBtn:        '#reset-btn'
  };

  for (const [key, selector] of Object.entries(simpleMap)) {
    const el = document.querySelector(selector);
    if (!el) {
      console.warn(`[ui-controller] Nodo no encontrado en el DOM: "${selector}"`);
    }
    _nodes[key] = el;
  }

  // Sliders
  for (const [key, ids] of Object.entries(_SLIDER_MAP)) {
    const inputEl   = document.querySelector(ids.inputId);
    const displayEl = document.querySelector(ids.displayId);

    if (!inputEl) {
      console.warn(`[ui-controller] Nodo no encontrado en el DOM: "${ids.inputId}"`);
    }
    if (!displayEl) {
      console.warn(`[ui-controller] Nodo no encontrado en el DOM: "${ids.displayId}"`);
    }

    _nodes.sliders[key].input   = inputEl;
    _nodes.sliders[key].display = displayEl;
  }

  // KPI toggles (NodeList, no se convierte a Array aquí)
  const kpiToggles = document.querySelectorAll('[data-kpi-toggle]');
  if (!kpiToggles || kpiToggles.length === 0) {
    console.warn('[ui-controller] No se encontraron elementos con [data-kpi-toggle] en el DOM.');
  }
  _nodes.kpiToggles = kpiToggles;
}

// ─── PASO 4: _bindSliders ─────────────────────────────────────────────────────
/**
 * Registra listeners 'input' en cada slider.
 * Sincroniza el display con el valor inicial sin disparar el callback.
 * Usa data-state-key del input para mapear al objeto state.
 * @private
 * @param {Object} stateRef - Referencia directa al objeto de estado global.
 * @param {Function} onChangeCallback - Callback a invocar tras cada cambio.
 */
function _bindSliders(stateRef, onChangeCallback) {
  for (const [, slider] of Object.entries(_nodes.sliders)) {
    const { input, display } = slider;

    if (!input || !display) continue;

    // Sincronización inicial sin disparar callback
    display.textContent = input.value;

    input.addEventListener('input', () => {
      const parsed   = parseFloat(input.value);
      const stateKey = input.getAttribute('data-state-key');

      if (stateKey && stateKey in stateRef) {
        stateRef[stateKey] = parsed;
      } else {
        console.warn(
          `[ui-controller] data-state-key "${stateKey}" no existe en stateRef.`
        );
      }

      display.textContent = parsed;
      onChangeCallback();
    });
  }
}

// ─── PASO 5: _bindToggles ─────────────────────────────────────────────────────
/**
 * Registra listeners 'click' en cada botón [data-kpi-toggle].
 * Alterna la propiedad booleana correspondiente en stateRef usando data-kpi-toggle
 * como clave. Refleja el estado activo/inactivo mediante classList.
 * @private
 * @param {Object} stateRef - Referencia directa al objeto de estado global.
 * @param {Function} onChangeCallback - Callback a invocar tras cada cambio.
 */
function _bindToggles(stateRef, onChangeCallback) {
  if (!_nodes.kpiToggles || _nodes.kpiToggles.length === 0) return;

  _nodes.kpiToggles.forEach((btn) => {
    const stateKey = btn.getAttribute('data-kpi-toggle');

    if (!stateKey) {
      console.warn('[ui-controller] Botón [data-kpi-toggle] sin valor de atributo.', btn);
      return;
    }

    // Sincronización inicial del estado visual
    if (stateRef[stateKey]) {
      btn.classList.add('is-active');
    } else {
      btn.classList.remove('is-active');
    }

    btn.addEventListener('click', () => {
      if (!(stateKey in stateRef)) {
        console.warn(
          `[ui-controller] data-kpi-toggle "${stateKey}" no existe en stateRef.`
        );
        return;
      }

      stateRef[stateKey] = !stateRef[stateKey];

      if (stateRef[stateKey]) {
        btn.classList.add('is-active');
      } else {
        btn.classList.remove('is-active');
      }

      onChangeCallback();
    });
  });
}

// ─── PASO 6: _bindOverdrive ───────────────────────────────────────────────────
/**
 * Registra el listener 'click' en el toggle de modo Overdrive.
 * Alterna stateRef.overdrive y refleja el estado en classList del botón.
 * @private
 * @param {Object} stateRef - Referencia directa al objeto de estado global.
 * @param {Function} onChangeCallback - Callback a invocar tras cada cambio.
 */
function _bindOverdrive(stateRef, onChangeCallback) {
  const btn = _nodes.overdriveToggle;
  if (!btn) return;

  // Sincronización inicial
  if (stateRef.overdrive) {
    btn.classList.add('is-active');
  } else {
    btn.classList.remove('is-active');
  }

  btn.addEventListener('click', () => {
    stateRef.overdrive = !stateRef.overdrive;

    if (stateRef.overdrive) {
      btn.classList.add('is-active');
    } else {
      btn.classList.remove('is-active');
    }

    onChangeCallback();
  });
}

// ─── PASO 7: _bindReset ───────────────────────────────────────────────────────
/**
 * Registra el listener 'click' en el botón de reset global.
 * Delega el reset al callback; no conoce los valores por defecto.
 * Tras el reset, re-sincroniza los displays de los sliders con los valores
 * que el estado haya recuperado, y actualiza classList de toggles.
 * @private
 * @param {Object} stateRef - Referencia directa al objeto de estado global.
 * @param {Function} onChangeCallback - Callback a invocar tras cada cambio.
 */
function _bindReset(stateRef, onChangeCallback) {
  const btn = _nodes.resetBtn;
  if (!btn) return;

  btn.addEventListener('click', () => {
    // El callback es responsable de restaurar stateRef a sus valores iniciales
    onChangeCallback('reset');

    // Re-sincronizar displays de sliders con los valores restaurados en stateRef
    for (const [, slider] of Object.entries(_nodes.sliders)) {
      const { input, display } = slider;
      if (!input || !display) continue;

      const stateKey = input.getAttribute('data-state-key');
      if (stateKey && stateKey in stateRef) {
        input.value         = stateRef[stateKey];
        display.textContent = stateRef[stateKey];
      }
    }

    // Re-sincronizar classList de KPI toggles
    if (_nodes.kpiToggles && _nodes.kpiToggles.length > 0) {
      _nodes.kpiToggles.forEach((toggleBtn) => {
        const stateKey = toggleBtn.getAttribute('data-kpi-toggle');
        if (!stateKey || !(stateKey in stateRef)) return;

        if (stateRef[stateKey]) {
          toggleBtn.classList.add('is-active');
        } else {
          toggleBtn.classList.remove('is-active');
        }
      });
    }

    // Re-sincronizar Overdrive toggle
    if (_nodes.overdriveToggle) {
      if (stateRef.overdrive) {
        _nodes.overdriveToggle.classList.add('is-active');
      } else {
        _nodes.overdriveToggle.classList.remove('is-active');
      }
    }
  });
}

// ─── PASO 2: initUIController (exportada) ────────────────────────────────────
/**
 * Punto de entrada único del módulo.
 * Cachea nodos y registra todos los listeners de la UI.
 *
 * @param {Object}   stateRef         - Referencia directa al objeto de estado global (state.js).
 * @param {Function} onChangeCallback - Función invocada tras cualquier cambio de control.
 *                                      Puede recibir un string opcional ('reset') como hint.
 */
export function initUIController(stateRef, onChangeCallback) {
  _cacheNodes();
  _bindSliders(stateRef, onChangeCallback);
  _bindToggles(stateRef, onChangeCallback);
  _bindOverdrive(stateRef, onChangeCallback);
  _bindReset(stateRef, onChangeCallback);
}

import { initState }        from './state.js';
import { initRenderer }     from './renderer.js';
import { initKpiEngine }    from './kpi-engine.js';
import { initCanvasEngine } from './canvas-engine.js';
import { initUIController } from './ui-controller.js';

/**
 * Orquesta la inicialización de todos los módulos de la aplicación.
 * ORDEN DE LLAMADA ES OBLIGATORIO:
 *   1. state       → fuente de verdad global
 *   2. kpi-engine  → registra los calculadores sobre el estado
 *   3. canvas-engine → inicializa los dos canvas superpuestos
 *   4. renderer    → arranca el bucle requestAnimationFrame
 *   5. ui-controller → enlaza los eventos del DOM al estado
 * @returns {void}
 */
function bootstrap() {
    initState();
    initKpiEngine();
    initCanvasEngine();
    initRenderer();
    initUIController();
}

document.addEventListener('DOMContentLoaded', bootstrap);
